/* @lc app=leetcode id=2861 lang=kotlin */ class Solution { fun maxNumberOfAlloys(n: Int, k: Int, budget: Int, composition: List<List<Int>>, stock: List<Int>, cost: List<Int>): Int = composition.maxOf { comp -> generateSequence(0L to 200000001L) { (l, r) -> if (l + 1 < r) ((l + r) / 2).let { m -> if ((0 until n).sumOf { j -> kotlin.math.max(0L, comp[j].toLong() * m - stock[j]) * cost[j] } <= budget.toLong()) m to r else l to m } else null }.last().first }.toInt() }